<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { RouterLink } from 'vue-router'
import { Activity, Download, RefreshCw, Search, ScanLine, TriangleAlert } from '@lucide/vue'
import { api, describeError } from '../api'
import RuntimeSafetyNotice from '../RuntimeSafetyNotice.vue'

interface Container { service:string; name:string; container_id:string|null; state:string; health:string|null; created_at:string|null; started_at:string|null;
 image:string|null; image_id:string|null; repo_digests:string[]; saved_image:string|null; baseline_image:string|null; saved_image_diff:string; baseline_image_diff:string;
 oom_killed:boolean|null; exit_code:number|null; restart_count:number|null; memory_limit_bytes:number|null; cpu_limit:number|null; read_only:boolean|null }
interface Parameter { model:string; service:string; state:string; source:string; actual_slots:number|null; actual_context:number|null;
 startup_slots:number|null; startup_context:number|null; saved_slots:number|null; saved_context:number|null; saved_available:boolean; baseline_slots:number|null; baseline_context:number|null;
 slots_baseline_diff:string; context_baseline_diff:string; slots_saved_diff:string; context_saved_diff:string }
interface Setting { id:string; label:string; env_key:string; unit:string; service:string; actual:number|string|boolean|null; saved:number|string|boolean|null; default:number|string|boolean|null; diff:string; active:boolean }
interface Event { id:string; service:string; at:string; observed_at:string; kind?:string; image?:string; image_id?:string; code?:string; source:string }
interface Operation { id:string; created_at:string; action:string; target:string; status:string; error:string; job_id:string; request_id:string }
interface Recovery { id:string; started_at:string|null; finished_at:string|null; status:string; mode:string; fault_codes:string[] }
interface Current { collected_at:string; cached:boolean; inventory_available:boolean; errors:string[]; configured_mode:string;
 baseline:{source:string;manifest_sha256:string;product:{current_version:string;default_mode:string}};
 containers:Container[]; parameters:Parameter[]; settings:Setting[]; configuration_files:{group:string;available:boolean;sha256:string|null}[];
 recoveries:Recovery[]; fault_scan:{since:string;tail_per_container:number;services:{service:string;available:boolean}[]} }
interface Snapshot { agent_available:boolean; audit_available:boolean; current:Current|null; history:{deployment:Event[];fault:Event[]}; operations:Operation[]; notice:string;history_notice:string;fault_notice:string }
const data = ref<Snapshot|null>(null), loading=ref(false), error=ref(''), tab=ref('runtime'), search=ref(''), onlyDiff=ref(false)
const current=computed(()=>data.value?.current)
const differenceCount=computed(()=>current.value ? current.value.settings.filter(i=>i.diff==='different').length
 +current.value.containers.filter(i=>i.saved_image_diff==='different'||i.baseline_image_diff==='different').length
 +current.value.parameters.filter(i=>[i.slots_baseline_diff,i.context_baseline_diff,i.slots_saved_diff,i.context_saved_diff].includes('different')).length : null)
const containers=computed(()=>(current.value?.containers||[]).filter(i=>`${i.service} ${i.name} ${i.image}`.toLowerCase().includes(search.value.toLowerCase())&&(!onlyDiff.value||i.saved_image_diff==='different'||i.baseline_image_diff==='different')))
const settings=computed(()=>(current.value?.settings||[]).filter(i=>`${i.label} ${i.env_key} ${i.service}`.toLowerCase().includes(search.value.toLowerCase())&&(!onlyDiff.value||i.diff==='different')))
const stateNames:Record<string,string>={running:'运行中',exited:'已停止',absent:'未创建',unknown:'未知',restarting:'重启中',created:'已创建',paused:'暂停',dead:'异常'}
const operationNames:Record<string,string>={restart:'服务重启','mode-switch':'模式切换','config-apply':'配置应用','device-recovery':'设备恢复','batch-file':'批量文件处理','api-test':'接口测试'}
const statusNames:Record<string,string>={succeeded:'成功',failed:'失败',unknown:'结果未知',accepted:'已提交',queued:'排队中',running:'执行中',interrupted:'已中断'}
const eventNames:Record<string,string>={first_observed:'容器创建 · 首次观测',container_replaced:'容器替换',process_restarted:'进程重启'}
function value(v:unknown){return v==null?'未确认':typeof v==='boolean'?(v?'是':'否'):String(v)}
function time(v:string|null|undefined){if(!v||v.startsWith('0001-'))return '未记录';const date=new Date(v);return Number.isNaN(date.getTime())?'未记录':date.toLocaleString('zh-CN',{hour12:false})}
function mb(v:number|null){return v==null?'未确认':v===0?'未设置':`${Math.round(v/1024/1024)} MiB`}
function difference(v:string){return ({same:'一致',different:'有差异',unknown:'未确认'} as Record<string,string>)[v]||'未确认'}
function selectTab(v:string){tab.value=v;search.value='';onlyDiff.value=false}
async function load(){if(loading.value)return;loading.value=true;error.value='';try{data.value=await api<Snapshot>('/api/diagnostics')}catch(e){error.value=describeError(e);data.value=null}finally{loading.value=false}}
onMounted(load)
</script>

<template>
 <section class="diagnostic-page">
  <RuntimeSafetyNotice />
  <div class="diagnostic-intro"><div><h2>让运行状态有据可查</h2><p>实际镜像与参数、配置差异、部署观测和故障线索。</p></div><div class="diagnostic-actions"><a href="/api/diagnostics/export.json" class="secondary-button"><Download :size="15"/>下载诊断快照</a><button class="secondary-button" :disabled="loading" @click="load"><RefreshCw :size="15" :class="{spin:loading}"/>{{loading?'采集中…':'重新采集'}}</button></div></div>
  <div class="diagnostic-notice"><ScanLine :size="20"/><div><strong>运行值、保存配置、版本基线分别核对</strong><p>{{data?.notice||'通过只读检查获取容器、服务上报参数与已保存配置。未采集到的数据明确标为未确认。'}}</p><small v-if="current">采集于 {{time(current.collected_at)}} · {{current.cached?'15 秒内缓存':'本次采集'}} · 保存模式 {{current.configured_mode}} · 基线默认模式 {{current.baseline.product.default_mode}}</small></div></div>
  <p v-if="error" class="notice error-notice" role="alert">{{error}}</p>
  <p v-if="data&&!data.agent_available" class="notice error-notice" role="alert">诊断代理暂不可用，实际运行信息未知。下方历史记录保留其原始时间，不能代表当前状态。</p>
  <p v-for="message in current?.errors||[]" :key="message" class="notice error-notice" role="alert">{{message}}</p>
  <div class="diagnostic-metrics"><article><Activity :size="17"/><strong>{{current?.inventory_available?current.containers.filter(i=>i.state==='running').length:'—'}} <small>/ {{current?.inventory_available?current.containers.length:'—'}}</small></strong><span>运行中 / 受管容器</span></article><article><ScanLine :size="17"/><strong>{{differenceCount??'—'}}</strong><span>存在差异的配置项 / 服务</span></article><article><TriangleAlert :size="17"/><strong>{{data?data.history.fault.length:'—'}}</strong><span>留存故障线索（最近 100 条）</span></article><article><strong class="version">{{current?.baseline.product.current_version||'—'}}</strong><span>版本清单基线 · 不等同实际安装版本</span></article></div>
  <section class="panel diagnostic-panel">
   <div class="tabs-bar" role="tablist" aria-label="诊断内容"><button v-for="item in [{id:'runtime',name:'实际运行'},{id:'config',name:'配置差异'},{id:'deployments',name:'最近部署'},{id:'faults',name:'故障与恢复'}]" :key="item.id" role="tab" :aria-selected="tab===item.id" :class="{active:tab===item.id}" @click="selectTab(item.id)">{{item.name}}</button></div>
   <div class="diagnostic-content">
    <p class="diagnostic-mobile-hint">表格可左右滑动，查看完整对照信息。</p>
    <p v-if="loading&&!data" class="diagnostic-empty">正在执行只读采集，请稍候…</p>
    <template v-if="tab==='runtime'">
     <div class="diagnostic-heading"><h3>槽位与上下文</h3><span>HLIELlama 服务的 /props 上报值</span></div>
     <p class="diagnostic-help">实际上下文为服务上报的每槽 n_ctx；启动 -c 的解释由运行时决定，页面不将其直接当作每槽值。未启动或上报失败时保留“未确认”。这些参数不代表长输入质量或并发性能已验收。</p>
     <div class="table-scroll"><table class="diagnostic-table parameter-table"><thead><tr><th>模型 / 状态</th><th>槽位：服务上报 / 保存 -np / 基线</th><th>每槽上下文：服务上报 / 基线</th><th>启动参数与保存参数</th><th>核对结果</th></tr></thead><tbody><tr v-for="item in current?.parameters||[]" :key="item.service" :data-model="item.model"><td><RouterLink :to="{path:'/capabilities',query:{model:item.model}}">{{item.model}}</RouterLink><small>{{stateNames[item.state]||item.state}} · {{item.source==='service_props'?'服务已上报':'无当前上报值'}}</small></td><td><strong>{{value(item.actual_slots)}}</strong> / {{item.saved_available?(item.saved_slots??'未显式设置'):'未读取'}} / {{value(item.baseline_slots)}}</td><td><strong>{{value(item.actual_context)}}</strong> / {{value(item.baseline_context)}}</td><td><small>启动 -np {{item.startup_slots??'未显式设置'}} · -c {{item.startup_context??'未显式设置'}}</small><small>保存 -np {{item.saved_available?(item.saved_slots??'未显式设置'):'未读取'}} · -c {{item.saved_available?(item.saved_context??'未显式设置'):'未读取'}}</small></td><td><span class="diagnostic-chip" :data-state="item.slots_baseline_diff">槽位基线 {{difference(item.slots_baseline_diff)}}</span><small>上下文基线 {{difference(item.context_baseline_diff)}}</small><small v-if="[item.slots_saved_diff,item.context_saved_diff].includes('different')">启动参数与保存配置有差异</small></td></tr></tbody></table></div>
     <div class="diagnostic-heading spaced"><h3>实际镜像与容器</h3><span>镜像 ID 标识实际制品；下方差异比较标签名，标签相同不代表内容相同</span></div>
     <div class="diagnostic-toolbar"><label><Search :size="15"/><input v-model="search" aria-label="搜索诊断容器" placeholder="搜索服务、容器或镜像"/></label><label><input v-model="onlyDiff" type="checkbox"/>只看镜像差异</label></div>
     <div class="diagnostic-containers"><article v-for="item in containers" :key="item.service" class="diagnostic-container"><header><strong>{{item.service}}</strong><span class="diagnostic-chip" :data-state="item.health==='unhealthy'?'different':item.state==='running'?'same':'unknown'">{{stateNames[item.state]||item.state}} · {{item.health||'无健康检查结果'}}</span></header><p>{{item.name}}</p><dl><dt>容器使用镜像</dt><dd>{{value(item.image)}}</dd><dt>实际镜像 ID</dt><dd class="mono">{{value(item.image_id)}}</dd><dt>保存配置镜像</dt><dd>{{value(item.saved_image)}} <span class="diagnostic-chip" :data-state="item.saved_image_diff">{{difference(item.saved_image_diff)}}</span></dd><dt>版本基线镜像</dt><dd>{{value(item.baseline_image)}} <span class="diagnostic-chip" :data-state="item.baseline_image_diff">{{difference(item.baseline_image_diff)}}</span></dd></dl><details><summary>资源、创建时间与摘要</summary><dl><dt>容器创建</dt><dd>{{time(item.created_at)}}</dd><dt>最近启动</dt><dd>{{time(item.started_at)}}</dd><dt>自动重启次数</dt><dd>{{value(item.restart_count)}}（容器生命周期累计）</dd><dt>内存 / CPU 限制</dt><dd>{{mb(item.memory_limit_bytes)}} / {{item.cpu_limit===0?'未设置':value(item.cpu_limit)}}</dd><dt>只读根文件系统</dt><dd>{{value(item.read_only)}}</dd><dt>OOM / 退出码</dt><dd>{{value(item.oom_killed)}} / {{value(item.exit_code)}}</dd><dt>容器 ID</dt><dd class="mono">{{value(item.container_id)}}</dd><dt>仓库摘要</dt><dd class="mono">{{item.repo_digests.join('\n')||'本地镜像无仓库摘要；使用上方实际镜像 ID 核对'}}</dd></dl></details></article></div>
    </template>
    <template v-else-if="tab==='config'">
     <div class="diagnostic-heading"><h3>容器环境与保存配置</h3><RouterLink to="/config">前往配置管理 →</RouterLink></div><p class="diagnostic-help">只展示允许的业务配置字段。容器环境是启动时的配置声明；缺失字段不以源码默认值冒充运行值。代理当前可读取网关、模型服务与 SenseVoice 的 Compose；管理台自身的保存镜像暂未挂载，标为未确认。</p>
     <div class="diagnostic-toolbar"><label><Search :size="15"/><input v-model="search" aria-label="搜索诊断配置" placeholder="搜索配置名、环境变量或服务"/></label><label><input v-model="onlyDiff" type="checkbox"/>只看配置差异</label></div>
     <div class="table-scroll"><table class="diagnostic-table"><thead><tr><th>配置项</th><th>容器启动环境</th><th>磁盘保存配置</th><th>源码默认</th><th>比较</th></tr></thead><tbody><tr v-for="item in settings" :key="item.id" :data-setting="item.id"><td>{{item.label}}<small>{{item.service}} · {{item.env_key}} {{item.unit}}</small></td><td>{{value(item.actual)}}<small v-if="!item.active">服务未运行</small></td><td>{{value(item.saved)}}</td><td>{{value(item.default)}}</td><td><span class="diagnostic-chip" :data-state="item.diff">{{difference(item.diff)}}</span></td></tr></tbody></table></div>
     <div class="diagnostic-files"><article v-for="file in current?.configuration_files||[]" :key="file.group"><strong>{{file.group}} · {{file.available?'已解析保存配置':'保存配置未确认'}}</strong><code>SHA-256 {{file.sha256||'未读取'}}</code></article><article v-if="current"><strong>版本基线来源：{{current.baseline.source}}</strong><code>规范化 JSON SHA-256 {{current.baseline.manifest_sha256}}</code></article></div>
    </template>
    <template v-else-if="tab==='deployments'">
     <h3>最近部署与启动观测</h3><p class="diagnostic-help">{{data?.history_notice}}</p><div class="table-scroll"><table class="diagnostic-table"><thead><tr><th>容器事件时间</th><th>服务 / 类型</th><th>镜像与实际 ID</th><th>首次记录时间</th></tr></thead><tbody><tr v-for="item in data?.history.deployment||[]" :key="item.id"><td>{{time(item.at)}}</td><td>{{item.service}}<small>{{eventNames[item.kind||'']||item.kind}}</small></td><td>{{item.image}}<small class="mono">{{item.image_id}}</small></td><td>{{time(item.observed_at)}}<small>来源 Docker inspect</small></td></tr></tbody></table></div><p v-if="data&&!data.history.deployment.length" class="diagnostic-empty">暂无部署观测记录，等待一次成功采集。</p>
     <h3 class="spaced">配置应用与管理操作</h3><p class="diagnostic-help">结果来自持久化管理审计；执行失败或结果未知不会记为部署成功。</p><div class="table-scroll"><table class="diagnostic-table"><thead><tr><th>时间</th><th>操作 / 目标</th><th>状态</th><th>关联标识</th></tr></thead><tbody><tr v-for="item in data?.operations.filter(i=>['restart','mode-switch','config-apply','device-recovery'].includes(i.action))||[]" :key="item.id"><td>{{time(item.created_at)}}</td><td>{{operationNames[item.action]||item.action}} · {{item.target}}</td><td>{{statusNames[item.status]||item.status}}</td><td><small>Job {{item.job_id||'—'}}</small><small>Request {{item.request_id||'—'}}</small></td></tr></tbody></table></div>
    </template>
    <template v-else>
     <h3>故障记录与恢复证据</h3><p class="diagnostic-help">{{data?.fault_notice}}</p><p v-if="current" class="diagnostic-help">本次扫描起点 {{time(current.fault_scan.since)}}，{{current.fault_scan.services.filter(i=>i.available).length}} / {{current.fault_scan.services.length}} 个容器日志读取成功；只存故障类别和时间，不导出原始日志。</p>
     <div class="table-scroll"><table class="diagnostic-table"><thead><tr><th>线索时间</th><th>服务</th><th>故障类别</th><th>来源 / 观测时间</th></tr></thead><tbody><tr v-for="item in data?.history.fault||[]" :key="item.id"><td>{{time(item.at)}}</td><td>{{item.service}}</td><td><span class="diagnostic-chip" data-state="different">{{item.code}}</span></td><td>{{item.source==='container_log'?'容器日志特征':'容器状态'}}<small>{{time(item.observed_at)}}</small></td></tr></tbody></table></div><p v-if="data&&!data.history.fault.length" class="diagnostic-empty">当前留存记录中没有故障线索；请结合扫描范围与下方恢复、审计记录判断。</p>
     <h3 class="spaced">已有设备恢复记录</h3><div class="diagnostic-recoveries"><article v-for="item in current?.recoveries||[]" :key="item.id"><strong>{{statusNames[item.status]||item.status}} · {{item.mode}}</strong><p>{{time(item.started_at)}} → {{time(item.finished_at)}}</p><code>{{item.id}}</code><small>故障特征：{{item.fault_codes.join(' / ')||'未记录特征'}} · 来源 device-recovery/result.json</small></article></div><p v-if="current&&!current.recoveries.length" class="diagnostic-empty">未读取到已有设备恢复证据。</p>
     <h3 class="spaced">失败或未确认的管理操作</h3><p v-if="data&&!data.audit_available" role="alert" class="notice error-notice">管理审计暂不可读取。</p><div class="diagnostic-recoveries"><article v-for="item in data?.operations.filter(i=>['failed','unknown','interrupted'].includes(i.status))||[]" :key="item.id"><strong>{{operationNames[item.action]||item.action}} · {{item.target}} · {{statusNames[item.status]}}</strong><p>{{time(item.created_at)}} {{item.error}}</p><small>Request {{item.request_id||'—'}} · Job {{item.job_id||'—'}}</small></article></div><RouterLink class="diagnostic-log-link" to="/logs">前往日志审计核对详情 →</RouterLink>
    </template>
   </div>
  </section>
 </section>
</template>

<style scoped>
